; ---------------------------------------------------------------------------
; Core B -- the Machinedrum's noise/metallic voice: hats, cymbals, maracas.
; Same ABI and trig convention as bd808.asm. Generated by dspnoise.py.
;
; Structure, measured (out/md-machines/NOTES.md section 15):
;   24-bit LCG noise -> resonant state-variable band-pass -> amp envelope
; The LCG is the 909's own, idiom for idiom (bd909.asm step 10, "noise: 24-bit
; LCG"): it is already gated bit-exact, so the one part of this engine that
; would be easiest to get subtly wrong is not new code.
;
; The band-pass is a Chamberlin SVF, two multiplies and two adds per sample:
;   high = noise - low - damp*band ;  band += f*high ;  low += f*band
; `band` is the output. f sets the centre, damp = 1/Q the width. Both are
; decoded from knobs through tables, so a machine is a pair of table indices.
; ---------------------------------------------------------------------------
zn01:
        move #>$ffffff,m0
        move #>$ffffff,m1
        move #>$ffffff,m4
; ⚠️ THE MACHINE IS THE BASE; THE KNOB IS AN OFFSET AROUND 64. The first
; version read PITCH, DECAY and WIDTH as absolute knob values, so a machine WAS
; its three knob defaults -- and `ab_engine_select` only ever writes the model
; id, never the knobs (deliberately: "stored patches retain their bytes" is the
; 808/909 contract). On an existing track all five core B rows therefore ran
; with the SAME three numbers and were the same machine. Jesse, 4 Oct 2026:
; "TRX OH and HH sounded the same as CH and are therefore not useful to have as
; separate engines." They were not separate engines; they were one engine read
; through whatever the Part happened to hold.
;
; So the three defining numbers come from NZ_BASE[model], packed one word per
; machine as band<<16 | decay<<8 | width, and each knob is a signed offset from
; 64. A row is then its own machine whatever a Part carries -- including a Part
; saved before this build -- and the knobs still sweep.
        move x:(r6+$6),a        ; the model id, as the glue left it
        and #>$f,a              ; only a noise-family model reaches here (M_ENGINE)
        move a1,n1
        move #>@NZBASE@,r1
        move x:(r1+n1),a
        move a,y1               ; the packed word, kept across every decode
; which RENDERER this machine is: engine<<21 | band<<14 | decay<<7 | width
; ⚠️ MASK THE ENGINE FIELD. It is bits 21..23 of a 24-bit word, so engine 4
; and up SET THE SIGN BIT -- `move x:(...),a` sign-extends into A2, `asr` keeps
; the sign, and ENG_FM (4) came out as -4. The band, decay and width fields
; escape this only because each of their extractions ends in an `and`.
;
; ⚠️ AND THE DISPATCH CHAIN BELOW HID IT FOR TWO BUILDS. Its last arm was an
; unconditional `bra zf01`, so EVERY unmatched value -- including -4 -- landed
; on the FM engine, which is where -4 was supposed to go. Adding a sixth
; engine moved the fall-through to the resonator bank and PL FM started
; rendering a resonator: a new engine appearing to break an old row, with the
; actual fault two years' worth of reading away from the symptom. Jesse's
; report on 5 Oct 2026 was "FM im not sure", which was the kindest possible
; description of a row that was only ever right by accident.
        move y1,a
        asr #$15,a,a
        and #>$7,a              ; three bits, unsigned: 0..7
        move a1,x0
        move x0,x:(r5+@ENG@)
; PITCH -> band centre
        move y1,a
        asr #$e,a,a
        and #>$7f,a             ; a1 = the band field
        move a1,x1
        move x:(r6+$0),a
        bsr zn09                ; the knob as a +-16 trim around 64
        move x1,b
        add b,a
        bsr zn08                ; clamp 0..127, halve, into n1
        move #>@N_F@,r1
        move x:(r1+n1),x0
        move x0,x:(r5+@F@)
; DECAY -> amplitude decay rate
        move y1,a
        asr #$7,a,a
        and #>$7f,a             ; a1 = the decay field
        move a1,x1
        move x:(r6+$1),a
        bsr zn09
        move x1,b
        add b,a
        bsr zn08
        move #>@N_DE@,r1
        move x:(r1+n1),x0
        move x0,x:(r5+@DE@)
; TONE -> band width (damp = 1/Q)
        move y1,a
        and #>$7f,a             ; a1 = the width field
        move a1,x1
        move x:(r6+$2),a
        bsr zn09
        move x1,b
        add b,a
        bsr zn08
        move #>@N_DAMP@,r1
        move x:(r1+n1),x0
        move x0,x:(r5+@DAMP@)
; ⚠️ THE SAME INDEX THROUGH THE FREQUENCY CURVE AS WELL. The width knob means
; "how narrow" to the SVF engines and "where the high-pass corner is" to the
; hat, so both lookups happen here while n1 still holds the index: N_DAMP for
; the one, N_F for the other. Two words, no second decode, no second table.
        move #>@N_F@,r1
        move x:(r1+n1),x0
        move x0,x:(r5+@HPK@)
; and the same knob as a plain 0..1 ramp, which is what a MIX is: N_VEL is a
; 128-entry i/127, so it takes the UNHALVED index zn08 left in y0.
        move y0,n1
        move #>@N_VEL@,r1
        move x:(r1+n1),a
        move a,x0
        move x0,x:(r5+@MIX@)
        move #>$7fffff,b
        move x0,y0
        sub y0,b                ; 1 - mix, the body's share
        move b,x:(r5+@BGN@)
; ACCNT -> output level
        move x:(r6+$7),a
        move a1,n1
        move #>@N_VEL@,r1
        move x:(r1+n1),x0
        move x0,x:(r5+@GAIN@)
; DRIVE (knob 5) -> folded into GAIN, which costs THREE instructions per sample
; instead of five.
; ⚠️ THE CLIPPER IS THE STORE'S OWN LIMITER, which is the same mechanism the
; "move a,x:(...) SATURATES" trap warns about -- used deliberately here. GAIN
; becomes gain/8 .. gain and every renderer's output stage ends with three
; `asl a`, so the signal is multiplied by 1x .. 8x and the store clamps what
; comes out past full scale. At knob 0 the two are exact inverses (1/8 and
; three shifts are both powers of two, and `mpy` keeps 48 bits before the
; store truncates), so a Part that has never touched this knob renders the
; same words as the build before it -- which `tools/harness/bdnoise.py`
; checks rather than assumes.
        move x:(r6+$5),a
        move a1,n1
        move #>@N_VEL@,r1
        move x:(r1+n1),x0       ; 0 .. 1
        move #>@DRV7@,y0
        mpy y0,x0,a             ; a = (1 - 1/8) * knob
        move #>@DRV1@,x0
        move x0,b
        add b,a                 ; a = 1/8 .. 1
        move a,x0
        move x:(r5+@GAIN@),y0
        mpy y0,x0,a
        move a,x:(r5+@GAIN@)
; ---- which renderer -------------------------------------------------------
; A chain rather than a jump table: this runs once per block per track, and an
; indirect `jsr (rn)` would need a register the glue's clobber list does not
; cover, which is the stock source continuation's to lose.
; ⚠️ `sub #imm` AND `jeq`, NOT `cmp`. AGENTS.md records `cmp a,b` having
; encoded as `max a,b` in this assembler, which updates only the carry bit
; while the branch tests N^V -- a dispatch is the worst possible place for
; that. Subtracting one at a time uses a form with 533 sites in the stock
; payload and sets every flag a Jcc reads. Absolute Jcc rather than a relative
; branch because the targets are in another file, concatenated after this one.
        move x:(r5+@ENG@),a
        tst a
        beq zn02                ; 0: band-passed noise, below
        sub #>$1,a
        beq zh01                ; 1: six square oscillators
        sub #>$1,a
        beq zs01                ; 2: two bodies + wires
        sub #>$1,a
        beq zp01                ; 3: a burst train
        sub #>$1,a
        beq zf01                ; 4: two-operator FM
        bra zr01                ; 5: four tuned resonators
zn02:
; ---- ENG_SVF's own two voicing knobs -------------------------------------
; SWEEP (knob 3): the band the filter glides TO over about 15 ms. The target
; is read through the SAME frequency curve as PITCH, offset by +-32 index
; steps, so knob 64 puts the target exactly on the band and the glide has
; nowhere to go -- the measured 5,046 Hz of TRX CH and OH is what a default
; Part still renders. Below 64 the hat falls, above it rises.
        move y1,a
        asr #$e,a,a
        and #>$7f,a             ; the band field again (y1 is still the word)
        move a1,x1
        move x:(r6+$3),a
        sub #>$40,a
        asr #$1,a,a             ; (knob - 64)/2: +-32 steps
        move a1,x0
        move x0,a
        move x1,b
        add b,a
        bsr zn08
        move #>@N_F@,r1
        move x:(r1+n1),x0
        move x0,x:(r5+@FT@)
; and the DISTANCE, once per block, so the sample loop is four instructions
; rather than nine: f_eff = FT - h*(FT - F), where h falls 1 -> 0.
        move x0,y0              ; y0 = the target
        move x:(r5+@F@),x1
        move x1,a               ; a = the band itself
        move y0,b
        sub a,b                 ; b = FT - F, signed, zero at knob 64
        move b,x:(r5+@FD@)
; ATK (knob 4): a bipolar transient shaper. A second envelope falls in 8 ms
; and is ADDED to the amplitude envelope with a signed depth: below 64 it
; subtracts (a softer attack), above it adds (a sharper click), and at 64 the
; depth is exactly zero.
; ⚠️ (knob-64) << 17 IS THE SIGNED DEPTH, in one instruction. a1 holds the
; integer, so shifting it 17 places puts -64..63 onto -1.0..0.992 in Q23;
; `move a1,x0` then takes it through a register, which neither limits nor
; leaves A2 stale behind a logical op.
        move x:(r6+$4),a
        sub #>$40,a
        asl #$11,a,a
        move a1,x0
        move x0,x:(r5+@ASC@)
; the trig convention is the 808's: knob $c is the frame offset, or negative
        move x:(r6+$c),a
        tst a
        blt zn03
        move a,x:(r5+@SEG@)
        bsr zn04
        bsr zn06
        move n7,a
        move x:(r5+@SEG@),x0
        sub x0,a
        bsr zn04
        rts
zn03:
        move n7,a
        bsr zn04
        rts
; --- zn09: a knob (0..127) becomes a +-16 trim around 64 -------------------
; ⚠️ THE SPAN IS A CORRECTNESS PROPERTY, NOT A TASTE SETTING. With the full
; +-64 range the sum clamps, and a Part holding 127 -- which is what a track
; carries once anyone turns a knob up -- puts TRX CH, TRX OH and TRX CY all on
; (127, 127, 127): one machine selected three ways, with every row sharing a
; band. That is what Jesse heard on 5 Oct 2026, having already told me the same
; thing about the build before. At 16 steps every pair of machines is separated
; in at least one parameter at EVERY knob position, checked exhaustively by
; dspnoise.separations() in the gate rather than argued for here.
;
; The shifted-out bits are dropped through x0 so this is exact floor division
; by four and dspnoise.index() can model it to the step -- `asr` leaves the
; remainder in a0, where it would otherwise survive into the second shift.
zn09:
        sub #>$40,a
        asr #$2,a,a
        move a1,x0
        move x0,a
        rts
; --- zn08: clamp a to 0..127 and halve it into n1 --------------------------
; base + (knob - 64) runs -64..190 and the tables hold 64 entries, so every
; decode ends here. Written with Tcc rather than a hand-rolled mask: a logical
; op leaves the extension byte stale and the next store saturates (AGENTS.md),
; and `tfr` rather than `move a,b` because an accumulator-to-accumulator move
; limits. Both constants are loaded BEFORE the op whose flags the Tcc reads --
; a move does not disturb the condition codes, arithmetic does.
zn08:
        move #$0,x0
        tst a
        tmi x0,a                ; below zero -> 0
        tfr a,b
        move #>$7f,a
        move #>$7f,x0
        sub b,a                 ; a = 127 - v, and the flags the Tcc reads
        tmi x0,b                ; above 127 -> 127
        tfr b,a
; ⚠️ BOTH INDICES COME BACK. n1 is the halved one the 64-entry curves want;
; y0 keeps the UNHALVED 0..127 value, because N_VEL is a 128-entry 0..1 ramp
; and the snare's mix wants exactly that. y0 is scratch everywhere in the
; decode -- y1 is the one that must survive, and it holds the packed word.
        move a1,y0
        asr #$1,a,a             ; 64-entry tables are indexed by the halved knob
        move a1,n1
        rts
; --- render `a` samples ----------------------------------------------------
zn04:
        tst a
        beq zn05
        do a,zn07
; the 909's LCG, unchanged in form: b0 carries the wrapping 24-bit product
        move x:(r5+@LCG@),x0
        move #>@LCGK@,y0
        mpy y0,x0,b             #0,x1
        add x,b                 #>@LCGC@,y0
        move #0,y1
        add y,b
        move b0,x0
        move x0,x:(r5+@LCG@)
        move x0,y1              ; the noise sample, parked: x0 and b are needed
; SWEEP: f_eff = FT - h*(FT - F), with h falling 1 -> 0 in about 15 ms.
; ⚠️ THE GLIDE'S STATE IS h, NOT f. The block decode rewrites F from the PITCH
; knob every block, so a glide that walked F itself would be reset sixteen
; samples into every note and the knob would do nothing audible at all -- the
; "not all of the parameters work" failure, built in by construction. h is the
; engine's own word, the trig sets it to 1, and it converges to 0 from any
; value, so a track that has never been trigged is no worse off than it already
; is with a stale BAND and LOW.
; `move b,x1` rather than `move b1,x1`: f_eff must LIMIT at full scale, not
; wrap to -1. At knob 64 the target IS the band, FD is zero, and f_eff is F to
; the bit -- which is how a default Part keeps the measured 5,046 Hz.
        move x:(r5+@FG@),b
        move b,x0
        move #>@SWRATE@,y0
        mpy y0,x0,a
        sub a,b                 ; h -= rate*h
        move b,x:(r5+@FG@)
        move b,y0               ; y0 = h
        move x:(r5+@FD@),x0
        mpy y0,x0,a             ; a = h * (FT - F), the signed side in x0
        move x:(r5+@FT@),b
        sub a,b
        move b,x1               ; x1 = f_eff
; ⚠️ F AND DAMP ARE STORED HALVED AND EVERY PRODUCT IS DOUBLED HERE WITH `asl`.
; A Chamberlin SVF needs f = 2*sin(pi*fc/SR), which is 1.82 at 16 kHz, and
; damp = 1/Q, which is up to 1.9 -- neither fits in Q23, so the tables hold
; half and the engine restores it. The first version did NOT restore it: its
; comment said "the engine's `mac` restores it", which is the exact belief
; AGENTS.md's own trap refutes -- `mpy`/`mac` align the Q46 product into Q47,
; so the HIGH word is the plain fractional product and nothing is doubled.
; Measured on 4 Oct 2026 after Jesse's unit: every machine's band came out at
; 0.55-0.59 of its target (CH 2,912 Hz against 5,046) and every Q was double
; what it was fitted to, which is why five machines with different numbers all
; sounded like one ringy hat. Doubling the PRODUCT is correct where doubling
; the accumulated state would not be: only the increment is scaled.
;
; Every multiply here is `mpy y0,x0` -- one of the two orders AGENTS.md records
; as encoding signed. The multiplier (f, damp, de, gain) is always in y0 and
; the signal always in x0, so no site can degrade into `mpysu` on a negative.
;
; high = noise - low - damp*band
        move x:(r5+@LOW@),y0
        move y1,b               ; b = the parked noise sample
        sub y0,b                ; b = noise - low
        move x:(r5+@BAND@),x0
        move x:(r5+@DAMP@),y0
        mpy y0,x0,a             ; a = (damp/2) * band
        asl a                   ; a = damp * band
        sub a,b                 ; b = high
; band += f*high
        move x1,y0              ; y0 = f_eff, from the glide above
        move b,x0               ; x0 = high
        mpy y0,x0,a             ; a = (f/2) * high
        asl a                   ; a = f * high
        move x:(r5+@BAND@),b
        add a,b
        move b,x:(r5+@BAND@)
; low += f*band
        move b,x0               ; x0 = the new band
        mpy y0,x0,a
        asl a
        move x:(r5+@LOW@),b
        add a,b
        move b,x:(r5+@LOW@)
; envelope: e -= de*e
        move x:(r5+@ENV@),b
        move b,x0
        move x:(r5+@DE@),y0
        mpy y0,x0,a             ; a = de * e
        sub a,b                 ; b = e - de*e
        move b,x:(r5+@ENV@)
; ATK: the transient envelope, and env_eff = env + asc*anv, floored at zero.
; ⚠️ `move b,y0` RATHER THAN `move b1,y0`, AND THE FLOOR IS NOT OPTIONAL. The
; sum reaches 2.0 at a positive depth, and moving the whole accumulator to a
; register limits it to 1.0 where moving b1 would WRAP it to -1 -- the hat's
; own "move a1,y1 is the wrap" note, read the other way round. At a negative
; depth the sum goes below zero for the first few milliseconds, which is the
; attack arriving PHASE-INVERTED; `tmi` floors it with a clean register.
        move x:(r5+@ANV@),a
        move a,x0
        move #>@ATKDE@,y0
        mpy y0,x0,a             ; a = atkde * anv
        move x0,b
        sub a,b
        move b,x:(r5+@ANV@)
        move b,x0
        move x:(r5+@ASC@),y0
        mpy y0,x0,a             ; a = depth * anv, signed
        move x:(r5+@ENV@),b
        add a,b
        move #$0,x0
        tst b
        tmi x0,b
        move b,y0               ; y0 = the envelope the output uses
; out = band * env * gain, into the stock source block
        move x:(r5+@BAND@),x0
        mpy y0,x0,a
        move a,x0
        move x:(r5+@GAIN@),y0
        mpy y0,x0,a
; DRIVE: GAIN already carries 1/8 .. 1, so three shifts give 1x .. 8x and the
; store below is the clipper.
        asl a
        asl a
        asl a
; ⚠️ TWO WORDS PER SAMPLE. The stock source block is INTERLEAVED STEREO: 16
; frames is 32 words, and bd909.asm writes every sample twice for exactly this
; reason. This wrote ONE word per sample for its first hardware outing, so the
; upper half of every block kept whatever was in X:$10..$1f -- the previous
; track's source samples, or this track's own previous frame. On Jesse's MK1
; (4 Oct 2026) that was all three reported faults at once: a hat on T2 "ring
; modded the 808 on T1 with a low bit rate sound" (alternate words were T1's
; kick), and TRX CY and TRX MA "rang out a continuous high pitched noise that
; kept going after the trig was removed, until the sequencer stopped" (the
; stale half of the attack repeating at the 2,756 Hz block rate). The engine's
; own envelope was decaying correctly the whole time.
        move a,x:(r0)+
        move a,x:(r0)+
zn07:
zn05:
        rts
; --- trigger ---------------------------------------------------------------
zn06:
; ⚠️ ZERO WHAT WE READ. These words are the 909's: a track that was a 909 and
; is now a hat leaves a filter mid-swing in BAND and LOW, and a resonator
; started from a large state rings on its own. Clearing them here is the whole
; price of sharing its voice block.
        clr a
        move a,x:(r5+@BAND@)
        move a,x:(r5+@LOW@)
        move #>$7fffff,a
        move a,x:(r5+@ENV@)
; the sweep's glide and the transient envelope both start FULL: h = 1 puts
; f_eff on the band itself, and the shaper's own envelope decays from there.
        move a,x:(r5+@FG@)
        move a,x:(r5+@ANV@)
        rts
